package i18n

var cloud_sync_gateway_commonEN = map[string]string{
	"cmd.cloud_sync_gateway.short":                                "Cloud sync gateway management",
	"cmd.cloud_sync_gateway.long":                                 "Cloud sync gateway management",
	"cmd.cloud_sync_gateway.examples":                             "hyperbdrctl cloud-sync-gateway list\nhyperbdrctl cloud-sync-gateway create --cloud-type aliyun --cloud-account-id <account_id>",
	"cmd.cloud_sync_gateway.notes":                                "- Root-level cloud-sync-gateway command group.\n- Use `create --cloud-type <provider>` for provider-specific creation parameters.",
	"cmd.cloud_sync_gateway.usage_line":                           "hyperbdrctl cloud-sync-gateway <command> [flags]",
	"cmd.cloud_sync_gateway.usage_notes":                          "List existing cloud sync gateways first:\n  hyperbdrctl cloud-sync-gateway list\n\nView one cloud sync gateway in detail:\n  hyperbdrctl cloud-sync-gateway detail --id <storage_id>\n\nBefore creating a cloud sync gateway, view the create help:\n  hyperbdrctl cloud-sync-gateway create --help\n\nAfter creation, wait for the task to complete:\n  hyperbdrctl cloud-sync-gateway wait --id <storage_id>\n\nBefore deletion, confirm the gateway details:\n  hyperbdrctl cloud-sync-gateway detail --id <storage_id>",
	"cmd.cloud_sync_gateway.list.short":                           "List cloud sync gateways",
	"cmd.cloud_sync_gateway.list.long":                            "List cloud sync gateways",
	"cmd.cloud_sync_gateway.list.usage_line":                      "hyperbdrctl cloud-sync-gateway list [flags]",
	"cmd.cloud_sync_gateway.list.usage_notes":                     "List cloud sync gateways by page.\n\nQuery the default page:\n  hyperbdrctl cloud-sync-gateway list\n\nTo restrict the result to one cloud account, run:\n  hyperbdrctl cloud-sync-gateway list --cloud-account-id <account_id>\n\nKeep the default type filter unless another type is required.\n\nAfter obtaining a cloud sync gateway ID, view its details:\n  hyperbdrctl cloud-sync-gateway detail --id <storage_id>",
	"cmd.cloud_sync_gateway.detail.short":                         "View cloud sync gateway details",
	"cmd.cloud_sync_gateway.detail.long":                          "View cloud sync gateway details",
	"cmd.cloud_sync_gateway.detail.usage_line":                    "hyperbdrctl cloud-sync-gateway detail --id <storage_id> [flags]",
	"cmd.cloud_sync_gateway.detail.usage_notes":                   "View the details of one cloud sync gateway.\n\nThe minimum query is:\n  hyperbdrctl cloud-sync-gateway detail --id <storage_id>\n\nThe cloud sync gateway ID usually comes from:\n  hyperbdrctl cloud-sync-gateway list",
	"cmd.cloud_sync_gateway.delete.usage_line":                    "hyperbdrctl cloud-sync-gateway delete [flags]",
	"cmd.cloud_sync_gateway.delete.usage_notes":                   "Delete one or more cloud sync gateways by ID.\n\nFind the target cloud sync gateway IDs first:\n  hyperbdrctl cloud-sync-gateway list\n\nParameter Sources:\n  --id string\n    Use when deleting one cloud sync gateway.\n\n  --ids string\n    Use when deleting multiple cloud sync gateways; separate IDs with commas.\n\nProvide at least one of --id and --ids.\n\nThe minimum single-delete command is:\n  hyperbdrctl cloud-sync-gateway delete --id <storage_id>\n\nTo delete multiple cloud sync gateways at once, run:\n  hyperbdrctl cloud-sync-gateway delete --ids <storage_id_1,storage_id_2>\n\nAdd the following flag only when the backend requires forced deletion:\n  --force\n\nAfter deletion returns, confirm that the cloud sync gateway was deleted:\n  hyperbdrctl cloud-sync-gateway list\n  hyperbdrctl cloud-sync-gateway detail --id <storage_id>",
	"cmd.cloud_sync_gateway.wait.usage_line":                      "hyperbdrctl cloud-sync-gateway wait [flags]",
	"cmd.cloud_sync_gateway.wait.usage_notes":                     "Wait for a cloud sync gateway creation task to reach a terminal state.\n\nThe cloud sync gateway ID usually comes from the create command result.\n\nAfter creation, wait for the task to complete:\n  hyperbdrctl cloud-sync-gateway wait --id <storage_id>\n\nTo adjust the polling interval, add:\n  --interval-seconds 15\n\nTo limit the maximum wait time, add:\n  --timeout-seconds 1800\n\nAfter the task finishes, view the cloud sync gateway details:\n  hyperbdrctl cloud-sync-gateway detail --id <storage_id>",
	"cmd.cloud_sync_gateway.create.short":                         "Create cloud sync gateway",
	"cmd.cloud_sync_gateway.create.long":                          "Create cloud sync gateway",
	"cmd.cloud_sync_gateway.create.usage_line":                    "hyperbdrctl cloud-sync-gateway create [flags]",
	"cmd.cloud_sync_gateway.create.examples":                      "hyperbdrctl cloud-sync-gateway create --cloud-type aliyun --cloud-account-id <account_id>\nhyperbdrctl cloud-sync-gateway create --cloud-type openstack --cloud-account-id <account_id> --boot-loader-image-id <windows_image_id>",
	"cmd.cloud_sync_gateway.create.usage_notes":                   "Use this cloud sync gateway creation entry point to view the create flags for a cloud account.\n\nList available cloud accounts first:\n  hyperbdrctl cloud-account list --storage-type block\n\nUse a cloud account ID to view the corresponding create flags:\n  hyperbdrctl cloud-sync-gateway create --cloud-account-id <account_id> --help",
	"cmd.cloud_sync_gateway.create.account.usage_line":            "hyperbdrctl cloud-sync-gateway create --cloud-account-id <account_id> [flags]",
	"cmd.cloud_sync_gateway.create.provider.usage_line":           "hyperbdrctl cloud-sync-gateway create --cloud-type %s [flags]",
	"cmd.block_storages.short":                                    "Target cloud-sync-gateway commands",
	"cmd.block_storages.long":                                     "Inspect target HyperGate storages, query gateway prerequisites, and enter validated cloud-sync-gateway creation flows.",
	"cmd.block_storages.examples":                                 "hyperbdrctl cloud-sync-gateway list --page 1 --page-size 100\nhyperbdrctl target cloud-sync-gateway resources --cloud-account-id <account_id> --region-id cn-beijing --zone-id cn-beijing-h --fetch-res flavors",
	"cmd.block_storages.notes":                                    "- Target-side HyperGate / cloud-sync-gateway command group.\n- Unknown flags are passed through as query parameters on read-only GET commands.",
	"cmd.block_storages.workflow":                                 "1. Choose an existing block-storage cloud account with `cloud-account list` or `cloud-account detail`.\n2. Query dependent resources with `target cloud-sync-gateway resources`.\n3. Query Windows repair-image candidates with `target cloud-sync-gateway resources --fetch-res win_hd_images` when needed.\n4. Confirm subnet defaults with `target cloud-sync-gateway subnet-config` when the selected network requires extra validation.\n5. Create the gateway with `target cloud-sync-gateway create aliyun` or `target cloud-sync-gateway create openstack`.",
	"cmd.block_storages.related":                                  "hyperbdrctl cloud-account list\nhyperbdrctl cloud-account detail --id <account_id>\nhyperbdrctl cloud-sync-gateway create --help",
	"cmd.block_storages.next_steps":                               "hyperbdrctl target cloud-sync-gateway resources --cloud-account-id <account_id> --region-id <region_id> --fetch-res zones --output json",
	"cmd.block_storages.list.short":                               "List block storages",
	"cmd.block_storages.list.long":                                "Query HyperGate block-storage resources with pagination.",
	"cmd.block_storages.list.examples":                            "hyperbdrctl cloud-sync-gateway list --page 1 --page-size 100\nhyperbdrctl cloud-sync-gateway list --cloud-account-id <account_id>\nhyperbdrctl --output json target cloud-sync-gateway list --type HyperGate",
	"cmd.block_storages.list.notes":                               "- Read-only API request.\n- Defaults type to HyperGate.\n- Use `--cloud-account-id` to filter by the target cloud account.",
	"cmd.block_storages.detail.short":                             "Show block storage detail",
	"cmd.block_storages.detail.long":                              "Fetch one HyperGate block-storage detail object by storage ID.",
	"cmd.block_storages.detail.examples":                          "hyperbdrctl cloud-sync-gateway detail --id <storage_id>\nhyperbdrctl --output json target cloud-sync-gateway detail --id <storage_id>",
	"cmd.block_storages.detail.notes":                             "- Read-only API request.\n- Use JSON output for full nested storage metadata and task state.",
	"cmd.block_storages.delete.short":                             "Delete cloud-sync-gateway",
	"cmd.block_storages.delete.long":                              "Delete one or more target cloud-sync-gateway storages by storage ID.",
	"cmd.block_storages.delete.examples":                          "hyperbdrctl cloud-sync-gateway delete --id <storage_id>\nhyperbdrctl cloud-sync-gateway delete --ids <storage_id_1,storage_id_2>\nhyperbdrctl cloud-sync-gateway delete --id <storage_id> --ids <storage_id_2,storage_id_3> --force",
	"cmd.block_storages.delete.notes":                             "- Mutating command.\n- Sends `delete_storage` directly to `/hypermotion/v1/storages/action`.\n- Add `--force` only when the backend requires a forced delete.",
	"cmd.block_storages.wait.short":                               "Wait for cloud-sync-gateway creation",
	"cmd.block_storages.wait.long":                                "Poll one target cloud-sync-gateway until the create result reaches success, failure, or timeout.",
	"cmd.block_storages.wait.examples":                            "hyperbdrctl cloud-sync-gateway wait --id <storage_id>\nhyperbdrctl --output json target cloud-sync-gateway wait --id <storage_id> --interval-seconds 10 --timeout-seconds 900",
	"cmd.block_storages.wait.notes":                               "- Polls the storage detail API.\n- Returns non-zero on failure or timeout.\n- Fails fast when the storage detail resolves to a non-gateway resource type.",
	"cmd.block_storages.resources.short":                          "Fetch gateway creation resources",
	"cmd.block_storages.resources.long":                           "Query account-scoped dependent resources for Alibaba Cloud block-gateway creation from an existing cloud account.",
	"cmd.block_storages.resources.examples":                       "hyperbdrctl target cloud-sync-gateway resources --cloud-account-id <account_id> --region-id cn-beijing --fetch-res zones --output json\nhyperbdrctl target cloud-sync-gateway resources --cloud-account-id <account_id> --region-id cn-beijing --zone-id cn-beijing-h --fetch-res networks,subnets --output json\nhyperbdrctl target cloud-sync-gateway resources --cloud-account-id <account_id> --region-id cn-beijing --zone-id cn-beijing-h --flavor-id ecs.t6-c1m2.large --fetch-res images,system_disk_types --output json\nhyperbdrctl target cloud-sync-gateway resources --cloud-account-id <account_id> --region-id cn-beijing --fetch-res win_hd_images,linux_hd_images --output json",
	"cmd.block_storages.resources.notes":                          "- Read-only helper command for the validated Alibaba Cloud block-gateway wizard.\n- fetch-res supports: regions, zones, flavors, images, win_hd_images, linux_hd_images, system_disk_types, networks, subnets, abilities.\n- `images` defaults to `image_type=system`; `linux_hd_images` defaults to `image_type=user_create`.",
	"cmd.block_storages.subnet_config.short":                      "Fetch block-storage subnet config",
	"cmd.block_storages.subnet_config.long":                       "Query post-VPC subnet defaults and validation details for block-gateway network configuration.",
	"cmd.block_storages.subnet_config.examples":                   "hyperbdrctl target cloud-sync-gateway subnet-config --cloud-account-id <account_id> --region-id cn-beijing --zone-id cn-beijing-h --network-id <vpc_id> --subnet-id <subnet_id>\nhyperbdrctl --output json target cloud-sync-gateway subnet-config --cloud-account-id <account_id> --cloud-type aliyun_bs --region-id cn-beijing --zone-id cn-beijing-h --network-id <vpc_id> --subnet-id <subnet_id>",
	"cmd.block_storages.subnet_config.notes":                      "- Read-only helper command.\n- Infers cloud-type from the cloud account when --cloud-type is omitted.",
	"cmd.block_storages.transition_images.short":                  "List block-storage transition images",
	"cmd.block_storages.transition_images.long":                   "List Windows transition images used by the final gateway step for UEFI-to-BIOS repair and driver adaptation.",
	"cmd.block_storages.transition_images.examples":               "hyperbdrctl target cloud-sync-gateway transition-images --cloud-account-id <account_id> --region-id cn-beijing --zone-id cn-beijing-h\nhyperbdrctl --output json target cloud-sync-gateway transition-images --cloud-account-id <account_id> --cloud-type aliyun_bs --region-id cn-beijing --zone-id cn-beijing-h --boot-mode bios",
	"cmd.block_storages.transition_images.notes":                  "- Read-only helper command.\n- Defaults match the validated Alibaba Cloud flow: purpose=rebuild_bcd, image_type=system, os_type=windows, boot_mode=bios.",
	"cmd.block_storages.create.short":                             "Create block storage gateway",
	"cmd.block_storages.create.long":                              "Create a block-storage cloud-sync-gateway through explicit cloud-specific workflows.",
	"cmd.block_storages.create.examples":                          "hyperbdrctl cloud-sync-gateway create aliyun --cloud-account-id <account_id>\nhyperbdrctl cloud-sync-gateway create openstack --cloud-account-id <account_id> --boot-loader-image-id <windows_image_id>",
	"cmd.block_storages.create.notes":                             "- Mutating command group.\n- Use the cloud-specific subcommands instead of the removed flat create path.",
	"cmd.target.cloud_sync_gateway.short":                         "Target cloud-sync-gateway commands",
	"cmd.target.cloud_sync_gateway.long":                          "Inspect target HyperGate storages, query cloud-sync-gateway prerequisites, and enter validated gateway creation flows.",
	"cmd.target.cloud_sync_gateway.examples":                      "hyperbdrctl cloud-sync-gateway list\nhyperbdrctl cloud-sync-gateway create --help",
	"cmd.target.cloud_sync_gateway.notes":                         "- `list` and `detail` inspect existing target HyperGate storages.\n- `delete` removes one or more existing gateway storages.\n- `resources` and `subnet-config` are prerequisite discovery commands.\n- `create` enters cloud-specific gateway creation flows.\n- `wait` polls one gateway until the create result settles.",
	"cmd.target.cloud_sync_gateway.usage_line":                    "hyperbdrctl target cloud-sync-gateway <command> [flags]",
	"cmd.target.cloud_sync_gateway.usage_notes":                   "Use this command group for target-side cloud-sync-gateway listing, deletion, prerequisite discovery, creation workflows, and post-create waiting.\n\nTo inspect the built-in cloud catalog first, run:\n  hyperbdrctl cloud-resource catalog\n\nTo inspect the required target cloud account first, run:\n  hyperbdrctl cloud-account list\n\nTo inspect existing target HyperGate storages, run:\n  hyperbdrctl cloud-sync-gateway list\n\nTo delete an existing gateway after you confirm its storage ID, run:\n  hyperbdrctl cloud-sync-gateway delete --help\n\nTo enter the validated gateway creation flows, run:\n  hyperbdrctl cloud-sync-gateway create --help\n\nAfter create returns a storage ID, wait for the final status with:\n  hyperbdrctl cloud-sync-gateway wait --id <storage_id>",
	"cmd.target.cloud_sync_gateway.list.usage_line":               "hyperbdrctl cloud-sync-gateway list [flags]",
	"cmd.target.cloud_sync_gateway.list.usage_notes":              "Use this command to query target HyperGate storages that already exist on the platform.\n\nTo query the default paged result, run:\n  hyperbdrctl cloud-sync-gateway list\n\nTo restrict the result to one target cloud account, add:\n  --cloud-account-id <account_id>\n\nThis command uses the default `HyperGate` type filter.\n\nTo inspect one storage after you obtain its ID, run:\n  hyperbdrctl cloud-sync-gateway detail --id <storage_id>",
	"cmd.target.cloud_sync_gateway.detail.usage_line":             "hyperbdrctl cloud-sync-gateway detail [flags]",
	"cmd.target.cloud_sync_gateway.detail.usage_notes":            "Use this command to fetch one target cloud-sync-gateway detail object by storage ID.\n\nThe minimum query is:\n  hyperbdrctl cloud-sync-gateway detail --id <storage_id>\n\n`storage_id` usually comes from:\n  hyperbdrctl cloud-sync-gateway list",
	"cmd.target.cloud_sync_gateway.delete.usage_line":             "hyperbdrctl cloud-sync-gateway delete [flags]",
	"cmd.target.cloud_sync_gateway.delete.usage_notes":            "Use this command to delete one or more existing target cloud-sync-gateway storages by storage ID.\n\nFind the target storage IDs first:\n  hyperbdrctl cloud-sync-gateway list\n\nThe minimum single-delete command is:\n  hyperbdrctl cloud-sync-gateway delete --id <storage_id>\n\nTo delete multiple storages in one request, run:\n  hyperbdrctl cloud-sync-gateway delete --ids <storage_id_1,storage_id_2>\n\nAdd `--force` only when the backend requires a forced delete.\n\nAfter delete returns, verify the remaining storages with:\n  hyperbdrctl cloud-sync-gateway list\n  hyperbdrctl cloud-sync-gateway detail --id <storage_id>",
	"cmd.target.cloud_sync_gateway.wait.usage_line":               "hyperbdrctl cloud-sync-gateway wait [flags]",
	"cmd.target.cloud_sync_gateway.wait.usage_notes":              "Use this command after a gateway create request has already been submitted.\n\nThe minimum wait command is:\n  hyperbdrctl cloud-sync-gateway wait --id <storage_id>\n\nUse `--interval-seconds` to reduce or increase the polling interval.\n\nUse `--timeout-seconds` to stop polling after a fixed wall-clock limit.\n\nTimeout only stops local polling. It does not cancel the backend create operation.",
	"cmd.target.cloud_sync_gateway.resources.usage_line":          "hyperbdrctl target cloud-sync-gateway resources [flags]",
	"cmd.target.cloud_sync_gateway.resources.usage_notes":         "Use this command to query account-scoped dependent resources for cloud-sync-gateway creation.\n\nThe minimum query is:\n  hyperbdrctl target cloud-sync-gateway resources --cloud-account-id <account_id>\n\nWhen `--fetch-res` is omitted, the CLI only sends the account context and lets the backend return its default resource set.\nIn the current OpenStack flow, that default response can already include project info, compute zones, images, flavors, networks, subnets, volume types, and Windows transition images.\n\nTo inspect raw fields for automation, add:\n  --output json\n\nTo limit the response to one resource group, add:\n  --fetch-res win_hd_images",
	"cmd.target.cloud_sync_gateway.subnet_config.usage_line":      "hyperbdrctl target cloud-sync-gateway subnet-config [flags]",
	"cmd.target.cloud_sync_gateway.subnet_config.usage_notes":     "Use this command to inspect subnet defaults and validation details for gateway network configuration.\n\nFor example:\n  hyperbdrctl target cloud-sync-gateway subnet-config --cloud-account-id <account_id> --zone-id <zone_id> --network-id <network_id>\n\nTo override the region explicitly, add:\n  --region-id <region_id>\n\nIf the saved account metadata is not enough, add:\n  --cloud-type <cloud_type>",
	"cmd.target.cloud_sync_gateway.transition_images.usage_line":  "hyperbdrctl target cloud-sync-gateway transition-images [flags]",
	"cmd.target.cloud_sync_gateway.transition_images.usage_notes": "Use this command to query the Windows transition images required by the gateway flow.\n\nFor example:\n  hyperbdrctl target cloud-sync-gateway transition-images --cloud-account-id <account_id> --region-id <region_id> --zone-id <zone_id>\n\nTo override the default boot mode, add:\n  --boot-mode <bios|uefi>\n\nTo inspect the raw image fields, add:\n  --output json",
	"cmd.target.cloud_sync_gateway.create.usage_line":             "hyperbdrctl cloud-sync-gateway create <provider> [flags]",
	"cmd.target.cloud_sync_gateway.create.usage_notes":            "Use this command group to enter block-storage cloud-sync-gateway creation flows by provider.\n\nConfirm the cloud account ID first:\n  hyperbdrctl cloud-account list\n  hyperbdrctl cloud-account detail --id <account_id>\n\nTo prepare creation inputs, start with:\n  hyperbdrctl target cloud-sync-gateway resources --cloud-account-id <account_id> --output json\n\nFor most providers, inspect subnet defaults only when the selected network needs extra validation:\n  hyperbdrctl target cloud-sync-gateway subnet-config --help\n\nOpenStack does not use `subnet-config` as a stable prerequisite in the current backend; inspect that flow directly with:\n  hyperbdrctl cloud-sync-gateway create openstack --help\n\nThen continue with a concrete provider command, for example:\n  hyperbdrctl cloud-sync-gateway create aliyun --help\n  hyperbdrctl cloud-sync-gateway create huawei --help\n\nAfter create returns a storage ID, continue with:\n  hyperbdrctl cloud-sync-gateway wait --id <storage_id>",
	"cmd.target.cloud_sync_gateway.create.provider.usage_line":    "hyperbdrctl cloud-sync-gateway create %s [flags]",
	"cmd.target.cloud_sync_gateway.create.provider.usage_notes":   "Use this command to create a block-storage cloud-sync-gateway for %s.\n\n`--cloud-type %s` maps to backend cloud_type `%s`.\n\nParameter Sources:\n  --cloud-account-id string\n    Comes from `cloud-account create --cloud-type %s --storage-type block`, or from `cloud-account list` / `cloud-account detail`.\n\n  Other resource flags\n    Start with:\n      hyperbdrctl target cloud-sync-gateway resources \\\n        --cloud-account-id <account_id> \\\n        --output json\n\n    If the selected network or subnet needs extra validation, then run:\n      hyperbdrctl target cloud-sync-gateway subnet-config --help\n\nThe minimum create command is:\n  hyperbdrctl cloud-sync-gateway create --cloud-type %s \\\n    --cloud-account-id <account_id>\n\nAdd region, zone, image, network, subnet, volume, and other overrides only when the current platform form requires them.\n\nTo override metadata paths, repeat either flag as needed:\n  --set path=value\n  --set-json path=<json>\n\nPaths are relative to create_storage.metadata. The override order is:\n  --set-json < --set < explicit create flags\n\nTo inspect the final request body first, add:\n  --preview-request\n\nAfter create returns a storage ID, continue with:\n  hyperbdrctl cloud-sync-gateway detail --id <storage_id>\n  hyperbdrctl cloud-sync-gateway wait --id <storage_id>",
	"cmd.block_storages.create_group.short":                       "Create target cloud-sync-gateway",
	"cmd.block_storages.create_group.long":                        "Create target cloud-sync-gateways through cloud-specific subcommands.",
	"cmd.block_storages.create_group.examples":                    "hyperbdrctl cloud-sync-gateway create aliyun --cloud-account-id <account_id>\nhyperbdrctl cloud-sync-gateway create openstack --cloud-account-id <account_id> --boot-loader-image-id <windows_image_id>",
	"cmd.block_storages.create_group.notes":                       "- Prefer the split subcommands below for validated gateway creation flows.\n- The older flat `target cloud-sync-gateway create --...` path has been removed.",
	"cmd.block_storages.create_group.workflow":                    "1. Pick the target cloud first.\n2. If resource IDs are still unknown, return to `target cloud-sync-gateway resources` or `target cloud-sync-gateway subnet-config`.\n3. Run the cloud-specific create subcommand with the resolved IDs and only the overrides you need.",
	"cmd.block_storages.create_group.related":                     "hyperbdrctl target cloud-sync-gateway resources --help\nhyperbdrctl target cloud-sync-gateway subnet-config --help\nhyperbdrctl target cloud-sync-gateway resources --cloud-account-id <account_id> --fetch-res win_hd_images --output json",
	"cmd.block_storages.create_group.next_steps":                  "hyperbdrctl cloud-sync-gateway create aliyun --help\nhyperbdrctl cloud-sync-gateway create openstack --help",
	"cmd.block_storages.create.provider.short":                    "Create %s block-storage cloud-sync-gateway",
	"cmd.block_storages.create.provider.long":                     "Create a block-storage cloud-sync-gateway for %s (`%s`).",
	"cmd.block_storages.create.provider.example":                  "hyperbdrctl cloud-sync-gateway create %s --cloud-account-id <account_id>",
}
